import { inject } from 'vue';
export const GS_CONTEXT_KEY = Symbol('gs-context');
export const GS_ITEM_CONTEXT_KEY = Symbol('gs-item-context');
export function useGsContext() {
    const ctx = inject(GS_CONTEXT_KEY);
    if (!ctx)
        throw new Error('useGridStack must be used within <GridStack>');
    return ctx;
}
export function useGsItemContext() {
    const ctx = inject(GS_ITEM_CONTEXT_KEY);
    if (!ctx)
        throw new Error('useGridStackItem must be used inside <GridStackItem> content');
    return ctx;
}
